def validate_branch(self) -> "ActionTargetEffectBranchProfile":
        """Reject contradictory applicability and incomplete save rules."""
        overlap = self.included_creature_types & self.excluded_creature_types
        if overlap:
            raise ValueError("included and excluded creature types cannot overlap")
        if self.resolution is OutcomeResolution.SAVING_THROW:
            if self.save_dc is None or self.save_ability is None:
                raise ValueError("saving-throw target effects require save_dc and save_ability")
        elif self.save_dc is not None or self.save_ability is not None:
            raise ValueError("save metadata is valid only for saving-throw target effects")
        return self

def validate_unique_effect_ids(self) -> "ActionTargetEffectProfile":
        """Require one unambiguous definition for each effect identity."""
        effect_ids = [branch.effect_id for branch in self.branches]
        if len(effect_ids) != len(set(effect_ids)):
            raise ValueError("target effect branch ids must be unique")
        return self

def validate_information_effect(self) -> "InformationEffectProfile":
        """Require coherent geometry and sense metadata."""
        if (self.shape is None) != (self.radius_feet is None):
            raise ValueError("information effect shape and radius_feet must be declared together")
        if self.operation is ActionInformationOperation.GRANT_SENSE:
            if self.sense_type is None:
                raise ValueError("grant-sense information effects require sense_type")
        elif self.sense_type is not None:
            raise ValueError("sense_type is valid only for grant-sense information effects")
        return self

def validate_topology_geometry(self) -> "TopologyEffectProfile":
        """Require shape and radius to describe one complete area contract."""
        if (self.shape is None) != (self.radius_feet is None):
            raise ValueError("topology effect shape and radius_feet must be declared together")
        return self

def validate_nonempty_world_effect(self) -> "ActionWorldEffectProfile":
        """Require at least one observable information or topology transition."""
        if not self.information_effects and not self.topology_effects:
            raise ValueError("world effect profiles require an information or topology effect")
        return self

def _validate_availability_status(self) -> "AvailableActionInfo":
        """Reject contradictory affordability and closed status facts."""
        source_unaffordable = (
            self.availability_status
            is ActionAvailabilityStatus.SOURCE_UNAFFORDABLE
        )
        if source_unaffordable == self.can_afford:
            raise ValueError(
                "source_unaffordable requires can_afford=false, while every "
                "other availability status requires can_afford=true"
            )
        available = (
            self.availability_status is ActionAvailabilityStatus.AVAILABLE
        )
        if available != bool(self.valid_targets):
            raise ValueError(
                "available requires at least one executable target, while "
                "every unavailable status requires an empty target list"
            )
        return self

def _validate_behavior_id(cls, value: str | None) -> str | None:
        if value is None:
            return None
        return validate_namespaced_id(value, "discovered behavior identity")

def _validate_behavior_id(cls, value: str | None) -> str | None:
        if value is None:
            return None
        return validate_namespaced_id(value, "discovered handler identity")

def serialize_uuid_set(self, value: Set[str]) -> List[str]:
        """Emit unordered UUID knowledge as a canonical JSON array."""
        return sorted(value)

def _normalize_equipment_sprites(
        cls,
        value: tuple[EquipmentSpritePresentation, ...],
    ) -> tuple[EquipmentSpritePresentation, ...]:
        layer_keys = [
            (row.equipment_slot, row.render_layer)
            for row in value
        ]
        if len(layer_keys) != len(set(layer_keys)):
            raise ValueError(
                "equipment presentation slot/layer pairs must be unique",
            )
        return tuple(sorted(
            value,
            key=lambda row: (
                row.equipment_slot.value,
                row.render_layer.value,
            ),
        ))

def validate_centering(self) -> "CubePresentationGeometry":
        """Require only directional cubes to carry an orientation."""
        if self.centered and self.direction is not None:
            raise ValueError("centered cube cannot carry a direction")
        if not self.centered and self.direction is None:
            raise ValueError("directional cube requires a direction")
        return self

def validate_segment(self) -> "WallSegment":
        if self.start == self.end:
            raise ValueError("A wall segment must have positive length")
        return self

def validate_path(self) -> "WallPolyline":
        if any(first == second for first, second in zip(self.points, self.points[1:])):
            raise ValueError("Consecutive wall vertices must differ")
        return self

def validate_shape(self) -> Self:
        """Require exact vertical and center/boundary shape semantics."""
        if not self.covered_supports:
            # Older records already carry this exact support identity.
            object.__setattr__(self, "covered_supports", (
                WorldObjectSupport(position=self.position, tile_uuid=self.tile_uuid),
            ))
        if len({support.position for support in self.covered_supports}) != len(self.covered_supports):
            raise ValueError("covered support positions must be unique")
        if WorldObjectSupport(position=self.position, tile_uuid=self.tile_uuid) not in self.covered_supports:
            raise ValueError("covered supports must contain the canonical anchor")
        if self.top_height_steps <= self.base_height_steps:
            raise ValueError(
                "top_height_steps must be greater than base_height_steps"
            )
        supports = {support.position for support in self.covered_supports}
        if len(set(self.removed_bands)) != len(self.removed_bands) or any(
                (x, y) not in supports or not self.base_height_steps <= height < self.top_height_steps
                for x, y, height in self.removed_bands):
            raise ValueError("removed bands must be unique cells of this object volume")
        if self.kind is WorldPlacementKind.CENTER:
            if self.boundary_direction is not None:
                raise ValueError(
                    "center placement cannot define boundary_direction"
                )
        elif self.boundary_direction is None:
            raise ValueError("boundary placement requires boundary_direction")
        elif len(self.covered_supports) != 1:
            raise ValueError("boundary placement has one owner Tile")
        return self

def validate_channels(self) -> Self:
        """Require unique channels in canonical order."""
        canonical = tuple(WorldEdgeChannel)
        if len(set(self.blocked_channels)) != len(self.blocked_channels):
            raise ValueError("blocked_channels must not contain duplicates")
        if tuple(
            channel
            for channel in canonical
            if channel in self.blocked_channels
        ) != self.blocked_channels:
            raise ValueError("blocked_channels must use canonical channel order")
        return self
